<?php get_header(); ?>
<section class="search-wrap"><div class="container"><header class="search-header"><span class="section-kicker"><?php echo esc_html( make_t( 'Resultados', 'Results' ) ); ?></span><h1><?php printf( esc_html( make_t( 'Resultados para “%s”', 'Results for “%s”' ) ), esc_html( get_search_query() ) ); ?></h1></header><div class="content-grid"><?php if ( have_posts() ) : while ( have_posts() ) : the_post(); ?><article class="post-card"><a href="<?php the_permalink(); ?>"><div class="post-card-media"><?php if ( has_post_thumbnail() ) the_post_thumbnail( 'make-journal' ); ?></div><div class="post-card-body"><span class="section-kicker"><?php echo esc_html( get_post_type() === 'product' ? make_t( 'Patrón', 'Pattern' ) : make_t( 'Artículo', 'Article' ) ); ?></span><h2><?php the_title(); ?></h2><p><?php echo esc_html( wp_trim_words( get_the_excerpt(), 20 ) ); ?></p></div></a></article><?php endwhile; else : ?><p><?php echo esc_html( make_t( 'No hemos encontrado nada con esa búsqueda.', 'We could not find anything for that search.' ) ); ?></p><?php endif; ?></div><div class="pagination"><?php the_posts_pagination(); ?></div></div></section>
<?php get_footer(); ?>
